import { DatabaseSync } from 'node:sqlite';
import { mkdirSync } from 'node:fs';
import { dirname } from 'node:path';

const SCHEMA = `
CREATE TABLE IF NOT EXISTS jobs (
  seq INTEGER PRIMARY KEY AUTOINCREMENT,
  id TEXT NOT NULL UNIQUE,
  status TEXT NOT NULL,
  input TEXT NOT NULL,
  steps INTEGER NOT NULL,
  fail_attempts INTEGER NOT NULL,
  attempts INTEGER NOT NULL DEFAULT 0,
  completed INTEGER NOT NULL DEFAULT 0,
  result_output TEXT,
  error TEXT,
  idempotency_key TEXT,
  available_at INTEGER NOT NULL DEFAULT 0,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
);
CREATE UNIQUE INDEX IF NOT EXISTS jobs_idempotency_key ON jobs (idempotency_key) WHERE idempotency_key IS NOT NULL;
CREATE INDEX IF NOT EXISTS jobs_queue ON jobs (status, available_at, seq);
CREATE TABLE IF NOT EXISTS meta (
  key TEXT PRIMARY KEY,
  value INTEGER NOT NULL
);
`;

/** Opens the SQLite database shared by the server and worker processes, creating the schema if needed. */
export function openDatabase(path: string = process.env.DATABASE_PATH ?? 'data/jobs.db'): DatabaseSync {
  if (path !== ':memory:') mkdirSync(dirname(path), { recursive: true });
  const db = new DatabaseSync(path);
  // busy_timeout first: switching to WAL takes a brief exclusive lock, and the server and worker
  // open the same database at once, so the loser must wait rather than fail.
  db.exec('PRAGMA busy_timeout = 5000; PRAGMA journal_mode = WAL;');
  db.exec(SCHEMA);
  return db;
}

/** Runs `fn` in a write transaction. BEGIN IMMEDIATE takes the write lock up front, so busy_timeout applies. */
export function immediate<T>(db: DatabaseSync, fn: () => T): T {
  db.exec('BEGIN IMMEDIATE');
  let result: T;
  try {
    result = fn();
    db.exec('COMMIT');
  } catch (e) {
    try {
      db.exec('ROLLBACK');
    } catch {
      // the original error is more useful
    }
    throw e;
  }
  return result;
}
/** Shared job types and the mapping from database rows to the API's job shape. */

export type JobStatus = 'queued' | 'running' | 'completed' | 'failed';

/** One row of the `jobs` table, as selected with `SELECT *`. */
export interface JobRow {
  seq: number;
  id: string;
  status: JobStatus;
  input: string;
  steps: number;
  fail_attempts: number;
  attempts: number;
  completed: number;
  result_output: string | null;
  error: string | null;
  idempotency_key: string | null;
  available_at: number;
  created_at: string;
  updated_at: string;
}

/** The job JSON returned by every endpoint that returns a job. */
export interface Job {
  id: string;
  status: JobStatus;
  input: string;
  steps: number;
  failAttempts: number;
  attempts: number;
  progress: { completed: number; total: number };
  result: { output: string } | null;
  error: string | null;
  createdAt: string;
  updatedAt: string;
}

/** Attempts allowed in total, including the first. */
export const MAX_ATTEMPTS = 3;
export const TRANSIENT_ERROR = 'transient failure';

export function nowIso(): string {
  return new Date().toISOString();
}

export function toJob(row: JobRow): Job {
  return {
    id: row.id,
    status: row.status,
    input: row.input,
    steps: row.steps,
    failAttempts: row.fail_attempts,
    attempts: row.attempts,
    progress: { completed: row.completed, total: row.steps },
    result: row.status === 'completed' ? { output: row.result_output ?? '' } : null,
    error: row.status === 'failed' ? row.error : null,
    createdAt: row.created_at,
    updatedAt: row.updated_at,
  };
}
/** Validation of `POST /api/jobs` requests. Collects every problem so the client can report them all. */

export interface FieldError {
  field: string;
  message: string;
}

export interface NewJob {
  input: string;
  steps: number;
  failAttempts: number;
  idempotencyKey: string | null;
}

export type ParseResult = { ok: true; job: NewJob } | { ok: false; fields: FieldError[] };

export const MAX_BODY_BYTES = 64 * 1024;
const KEY_PATTERN = /^[A-Za-z0-9_-]{1,128}$/;
const KNOWN_FIELDS = new Set(['input', 'steps', 'failAttempts']);

export function isJsonContentType(value: string | undefined): boolean {
  if (value === undefined) return false;
  return (value.split(';')[0] ?? '').trim().toLowerCase() === 'application/json';
}

function isPlainObject(v: unknown): v is Record<string, unknown> {
  return typeof v === 'object' && v !== null && !Array.isArray(v);
}

function integerField(fields: FieldError[], obj: Record<string, unknown>, name: string, min: number, max: number, fallback: number): number {
  const v = obj[name];
  if (v === undefined) return fallback;
  if (typeof v !== 'number' || !Number.isInteger(v) || v < min || v > max) {
    fields.push({ field: name, message: `must be an integer from ${min} to ${max}` });
    return fallback;
  }
  return v;
}

/**
 * @param body the raw request body, or undefined when it could not be read or exceeds MAX_BODY_BYTES
 */
export function parseSubmission(args: { contentType: string | undefined; body: string | undefined; idempotencyKey: string | undefined }): ParseResult {
  const fields: FieldError[] = [];
  if (!isJsonContentType(args.contentType)) {
    fields.push({ field: 'body', message: 'Content-Type must be application/json' });
  }

  let obj: Record<string, unknown> | undefined;
  if (args.body === undefined) {
    fields.push({ field: 'body', message: `request body is missing or larger than ${MAX_BODY_BYTES} bytes` });
  } else {
    let parsed: unknown;
    let isJson = true;
    try {
      parsed = JSON.parse(args.body);
    } catch {
      isJson = false;
    }
    if (!isJson) fields.push({ field: 'body', message: 'request body must be valid JSON' });
    else if (!isPlainObject(parsed)) fields.push({ field: 'body', message: 'request body must be a JSON object' });
    else obj = parsed;
  }

  if (args.idempotencyKey !== undefined && !KEY_PATTERN.test(args.idempotencyKey)) {
    fields.push({ field: 'Idempotency-Key', message: 'must be 1 to 128 characters: letters, digits, "_" or "-"' });
  }

  if (obj) {
    for (const key of Object.keys(obj)) {
      if (!KNOWN_FIELDS.has(key)) fields.push({ field: key, message: 'is not a recognised field' });
    }
    const input = obj.input;
    if (input === undefined) fields.push({ field: 'input', message: 'is required' });
    else if (typeof input !== 'string') fields.push({ field: 'input', message: 'must be a string' });
    else if (input.length < 1 || input.length > 1000) fields.push({ field: 'input', message: 'must be 1 to 1000 characters' });
    else if (input.trim() === '') fields.push({ field: 'input', message: 'must not be only whitespace' });
    const steps = integerField(fields, obj, 'steps', 1, 20, 5);
    const failAttempts = integerField(fields, obj, 'failAttempts', 0, 5, 0);

    if (fields.length === 0 && typeof input === 'string') {
      return {
        ok: true,
        job: { input, steps, failAttempts, idempotencyKey: args.idempotencyKey ?? null },
      };
    }
  }
  return { ok: false, fields };
}
import { createServer, type IncomingMessage, type ServerResponse } from 'node:http';
import { readFileSync } from 'node:fs';
import { randomUUID } from 'node:crypto';
import { immediate, openDatabase } from './db.ts';
import { nowIso, toJob, type JobRow } from './jobs.ts';
import { MAX_BODY_BYTES, parseSubmission, type FieldError } from './validate.ts';

/** The worker counts as up if its heartbeat (written about once a second) is at most this old. */
const HEARTBEAT_FRESH_MS = 3_000;
const JOB_PATH = /^\/api\/jobs\/([^/]+)$/;

const db = openDatabase();
const uiHtml = readFileSync(new URL('../ui/index.html', import.meta.url), 'utf8');

type Outcome = { kind: 'created' | 'replay'; row: JobRow } | { kind: 'conflict' };

function sendJson(res: ServerResponse, status: number, body: unknown, headers: Record<string, string> = {}): void {
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8', ...headers });
  res.end(JSON.stringify(body));
}

function sendError(res: ServerResponse, status: number, code: string, message: string, fields?: FieldError[]): void {
  const error: { code: string; message: string; fields?: FieldError[] } = { code, message };
  if (fields) error.fields = fields;
  sendJson(res, status, { error });
}

function methodNotAllowed(res: ServerResponse, allow: string): void {
  sendJson(res, 405, { error: { code: 'method_not_allowed', message: `Method not allowed. Allowed: ${allow}.` } }, { allow });
}

function readBody(req: IncomingMessage): Promise<string | undefined> {
  return new Promise((resolve) => {
    const chunks: Buffer[] = [];
    let size = 0;
    let tooLarge = false;
    req.on('data', (chunk: Buffer) => {
      size += chunk.length;
      if (size > MAX_BODY_BYTES) tooLarge = true;
      else chunks.push(chunk);
    });
    req.on('end', () => resolve(tooLarge ? undefined : Buffer.concat(chunks).toString('utf8')));
    req.on('error', () => resolve(undefined));
  });
}

function selectById(id: string): JobRow | undefined {
  return db.prepare('SELECT * FROM jobs WHERE id = ?').get(id) as unknown as JobRow | undefined;
}

async function createJob(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const body = await readBody(req);
  const keyHeader = req.headers['idempotency-key'];
  // A repeated header arrives as an array; joined, it fails the key pattern and is rejected.
  const key = Array.isArray(keyHeader) ? keyHeader.join(', ') : keyHeader;
  const parsed = parseSubmission({ contentType: req.headers['content-type'], body, idempotencyKey: key });
  if (!parsed.ok) {
    sendError(res, 400, 'invalid_request', 'The job submission is invalid.', parsed.fields);
    return;
  }
  const submission = parsed.job;

  // Node runs this synchronously, and the write transaction serialises it against the worker.
  const outcome = immediate<Outcome>(db, () => {
    if (submission.idempotencyKey !== null) {
      const existing = db
        .prepare('SELECT * FROM jobs WHERE idempotency_key = ?')
        .get(submission.idempotencyKey) as unknown as JobRow | undefined;
      if (existing) {
        const samePayload =
          existing.input === submission.input &&
          existing.steps === submission.steps &&
          existing.fail_attempts === submission.failAttempts;
        return samePayload ? { kind: 'replay', row: existing } : { kind: 'conflict' };
      }
    }
    const id = randomUUID();
    const now = nowIso();
    db.prepare(
      `INSERT INTO jobs (id, status, input, steps, fail_attempts, attempts, completed, result_output, error,
                         idempotency_key, available_at, created_at, updated_at)
       VALUES (?, 'queued', ?, ?, ?, 0, 0, NULL, NULL, ?, 0, ?, ?)`,
    ).run(id, submission.input, submission.steps, submission.failAttempts, submission.idempotencyKey, now, now);
    return { kind: 'created', row: selectById(id)! };
  });

  if (outcome.kind === 'conflict') {
    sendError(res, 409, 'idempotency_conflict', 'This Idempotency-Key was already used with a different submission.');
    return;
  }
  sendJson(res, outcome.kind === 'created' ? 201 : 200, toJob(outcome.row));
}

function listJobs(res: ServerResponse): void {
  const rows = db.prepare('SELECT * FROM jobs ORDER BY seq DESC').all() as unknown as JobRow[];
  sendJson(res, 200, { jobs: rows.map(toJob) });
}

function getJob(res: ServerResponse, id: string): void {
  const row = selectById(id);
  if (!row) {
    sendError(res, 404, 'not_found', `No job with id ${id}.`);
    return;
  }
  sendJson(res, 200, toJob(row));
}

function health(res: ServerResponse): void {
  const hb = db.prepare("SELECT value FROM meta WHERE key = 'worker_heartbeat'").get() as unknown as { value: number } | undefined;
  const up = hb !== undefined && Date.now() - hb.value < HEARTBEAT_FRESH_MS;
  sendJson(res, 200, { status: 'ok', worker: up ? 'up' : 'down' });
}

async function route(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const { pathname } = new URL(req.url ?? '/', 'http://localhost');
  const method = req.method ?? 'GET';

  if (pathname === '/health') {
    return method === 'GET' ? health(res) : methodNotAllowed(res, 'GET');
  }
  if (pathname === '/') {
    if (method !== 'GET') return methodNotAllowed(res, 'GET');
    res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' });
    res.end(uiHtml);
    return;
  }
  if (pathname === '/api/jobs') {
    if (method === 'GET') return listJobs(res);
    if (method === 'POST') return createJob(req, res);
    return methodNotAllowed(res, 'GET, POST');
  }
  const match = JOB_PATH.exec(pathname);
  if (match) {
    if (method !== 'GET') return methodNotAllowed(res, 'GET');
    let id: string;
    try {
      id = decodeURIComponent(match[1]!);
    } catch {
      return sendError(res, 404, 'not_found', 'No such job.');
    }
    return getJob(res, id);
  }
  sendError(res, 404, 'not_found', `No route for ${method} ${pathname}.`);
}

const server = createServer((req, res) => {
  route(req, res).catch((e: unknown) => {
    console.error('request failed:', e);
    if (!res.headersSent) sendError(res, 500, 'internal_error', 'Unexpected server error.');
    else res.end();
  });
});

const port = Number(process.env.PORT ?? 3000);
server.listen(port, () => console.log(`server listening on ${port}`));

let shuttingDown = false;
function shutdown(): void {
  if (shuttingDown) return;
  shuttingDown = true;
  server.close(() => {
    db.close();
    process.exit(0);
  });
  server.closeAllConnections();
}
process.on('SIGTERM', shutdown);
process.on('SIGINT', shutdown);
import { setTimeout as sleep } from 'node:timers/promises';
import { immediate, openDatabase } from './db.ts';
import { MAX_ATTEMPTS, nowIso, TRANSIENT_ERROR, type JobRow } from './jobs.ts';

const STEP_MS = 100;
const RETRY_DELAY_MS = 500;
const IDLE_POLL_MS = 200;
const HEARTBEAT_MS = 1_000;

const db = openDatabase();
let stopping = false;
for (const signal of ['SIGINT', 'SIGTERM'] as const) {
  process.on(signal, () => {
    stopping = true;
  });
}

function beat(value: number): void {
  db.prepare(
    `INSERT INTO meta (key, value) VALUES ('worker_heartbeat', ?)
     ON CONFLICT (key) DO UPDATE SET value = excluded.value`,
  ).run(value);
}

// Any job still "running" was interrupted when the previous worker stopped. Its attempt was
// started, so it counts, but it has no result yet: put it back in the queue to run again.
immediate(db, () =>
  db.prepare(`UPDATE jobs SET status = 'queued', completed = 0, available_at = 0, updated_at = ? WHERE status = 'running'`).run(nowIso()),
);

beat(Date.now());
const heartbeat = setInterval(() => {
  try {
    beat(Date.now());
  } catch (e) {
    console.error('heartbeat failed:', e);
  }
}, HEARTBEAT_MS);

/** Claims the oldest queued job whose retry delay has passed and starts an attempt on it. */
function claim(): JobRow | undefined {
  return immediate<JobRow | undefined>(db, () => {
    const row = db
      .prepare(`SELECT * FROM jobs WHERE status = 'queued' AND available_at <= ? ORDER BY seq LIMIT 1`)
      .get(Date.now()) as unknown as JobRow | undefined;
    if (!row) return undefined;
    const attempts = row.attempts + 1;
    db.prepare(`UPDATE jobs SET status = 'running', attempts = ?, completed = 0, updated_at = ? WHERE seq = ?`).run(
      attempts,
      nowIso(),
      row.seq,
    );
    return { ...row, status: 'running' as const, attempts, completed: 0 };
  });
}

function requeue(seq: number, availableAt: number): void {
  db.prepare(`UPDATE jobs SET status = 'queued', completed = 0, available_at = ?, updated_at = ? WHERE seq = ?`).run(
    availableAt,
    nowIso(),
    seq,
  );
}

async function runAttempt(job: JobRow): Promise<void> {
  const attempt = job.attempts;

  // Simulated transient failure: the attempt fails at its first step, before any progress.
  if (attempt <= job.fail_attempts) {
    if (attempt < MAX_ATTEMPTS) {
      requeue(job.seq, Date.now() + RETRY_DELAY_MS);
    } else {
      db.prepare(`UPDATE jobs SET status = 'failed', error = ?, result_output = NULL, updated_at = ? WHERE seq = ?`).run(
        TRANSIENT_ERROR,
        nowIso(),
        job.seq,
      );
    }
    return;
  }

  for (let step = 1; step <= job.steps; step++) {
    if (stopping) {
      // Shutting down mid-job: hand it back so the next worker run starts it again.
      requeue(job.seq, 0);
      return;
    }
    await sleep(STEP_MS);
    db.prepare(`UPDATE jobs SET completed = ?, updated_at = ? WHERE seq = ?`).run(step, nowIso(), job.seq);
  }

  db.prepare(
    `UPDATE jobs SET status = 'completed', completed = ?, result_output = ?, error = NULL, updated_at = ? WHERE seq = ?`,
  ).run(job.steps, job.input.toUpperCase(), nowIso(), job.seq);
}

console.log('worker started');
while (!stopping) {
  try {
    const job = claim();
    if (!job) {
      await sleep(IDLE_POLL_MS);
      continue;
    }
    await runAttempt(job);
  } catch (e) {
    console.error('worker error:', e);
    await sleep(1_000);
  }
}

clearInterval(heartbeat);
beat(0);
db.close();
console.log('worker stopped');
