<body>
  <h1>Job tracker</h1>

  <form data-testid="job-form" id="job-form" novalidate>
    <label>Input
      <input data-testid="job-input" name="input" type="text" autocomplete="off">
    </label>
    <label>Steps
      <input data-testid="job-steps" name="steps" type="text" inputmode="numeric" value="5">
    </label>
    <label>Fail attempts
      <input data-testid="job-fail-attempts" name="failAttempts" type="text" inputmode="numeric" value="0">
    </label>
    <button data-testid="job-submit" type="submit">Submit</button>
  </form>

  <div data-testid="form-error" role="alert"></div>

  <h2>Jobs</h2>
  <ul data-testid="job-list"></ul>

  <script>
    const form = document.querySelector('[data-testid="job-form"]');
    const inputEl = document.querySelector('[data-testid="job-input"]');
    const stepsEl = document.querySelector('[data-testid="job-steps"]');
    const failEl = document.querySelector('[data-testid="job-fail-attempts"]');
    const submitBtn = document.querySelector('[data-testid="job-submit"]');
    const errorEl = document.querySelector('[data-testid="form-error"]');
    const listEl = document.querySelector('[data-testid="job-list"]');

    // Numeric-looking text becomes a number; anything else is sent as typed so the API rejects it.
    function asValue(text) {
      const t = text.trim();
      return /^[-+]?\d+(\.\d+)?$/.test(t) ? Number(t) : text;
    }

    function describeError(data, status) {
      const err = data && data.error;
      if (!err) return `Request failed (HTTP ${status}).`;
      const lines = [err.message || err.code || `HTTP ${status}`];
      for (const f of err.fields || []) lines.push(`${f.field}: ${f.message}`);
      return lines.join('\n');
    }

    form.addEventListener('submit', async (event) => {
      event.preventDefault();
      errorEl.textContent = '';
      const body = { input: inputEl.value };
      if (stepsEl.value.trim() !== '') body.steps = asValue(stepsEl.value);
      if (failEl.value.trim() !== '') body.failAttempts = asValue(failEl.value);
      submitBtn.disabled = true;
      try {
        const res = await fetch('/api/jobs', {
          method: 'POST',
          headers: { 'content-type': 'application/json' },
          body: JSON.stringify(body),
        });
        const data = await res.json().catch(() => null);
        if (!res.ok) {
          errorEl.textContent = describeError(data, res.status);
          return;
        }
        inputEl.value = '';
        await refresh();
      } catch (e) {
        errorEl.textContent = `Could not reach the server: ${e.message}`;
      } finally {
        submitBtn.disabled = false;
      }
    });

    function el(tag, className, text) {
      const node = document.createElement(tag);
      if (className) node.className = className;
      if (text !== undefined) node.textContent = text;
      return node;
    }

    function renderJob(job) {
      const li = el('li');
      li.setAttribute('data-testid', 'job-item');
      li.dataset.jobId = job.id;

      const row = el('div', 'row');
      const status = el('span', `status-${job.status}`, job.status);
      status.setAttribute('data-testid', 'job-status');
      const progress = el('span', '', `${job.progress.completed}/${job.progress.total}`);
      progress.setAttribute('data-testid', 'job-progress');
      row.append(status, progress, el('span', 'id', job.id));

      const input = el('div', 'text', job.input);
      const result = el('div', 'text');
      result.setAttribute('data-testid', 'job-result');
      if (job.status === 'completed') result.textContent = job.result.output;
      else if (job.status === 'failed') result.textContent = job.error;

      li.append(row, input, result);
      return li;
    }

    let lastJson = '';
    async function refresh() {
      let text;
      try {
        const res = await fetch('/api/jobs', { cache: 'no-store' });
        if (!res.ok) return;
        text = await res.text();
      } catch {
        return;
      }
      if (text === lastJson) return;
      lastJson = text;
      const { jobs } = JSON.parse(text);
      listEl.replaceChildren(...jobs.map(renderJob));
    }

    refresh();
    setInterval(refresh, 1000);
  </script>
